<?php
if(PHP_SAPI!=='cli'||getenv('APP_ENV')!=='testing'||!preg_match('/^impe_test_handly_aliados_union_[a-z0-9_]+$/D',getenv('IMPE_DB_NAME')?:''))exit(2);
require_once __DIR__.'/../config/db_connection.php';
require_once __DIR__.'/../tools/lib/UnificarBachillerato.php';
require_once __DIR__.'/../app/services/AliadoRegistroService.php';
require_once __DIR__.'/../app/services/FormularioAliadoService.php';
require_once __DIR__.'/../app/models/FormularioRegistroModel.php';
$db=(new Database())->connect(false);$checks=0;
$check=static function($v,$name)use(&$checks){if(!$v)throw new RuntimeException($name);$checks++;echo "OK $name\n";};
$reject=static function(callable $fn,$name)use($check){try{$fn();}catch(Throwable $e){$check(true,$name.' ('.$e->getMessage().')');return;}throw new RuntimeException('Se aceptó: '.$name);};
$private=sys_get_temp_dir().'/impe-union-'.bin2hex(random_bytes(5));mkdir($private,0700);
$db->query("INSERT INTO formulario_programas (codigo,nombre,activo) VALUES ('bachillerato-286','Bachillerato 286',1) ON DUPLICATE KEY UPDATE nombre=VALUES(nombre),activo=1");
$db->query("INSERT INTO formulario_programas (codigo,nombre,activo) VALUES ('bachillerato-general','Bachillerato General',1) ON DUPLICATE KEY UPDATE nombre=VALUES(nombre),activo=1");
$perfil=$db->query('SELECT r.aliado_id,a.token FROM formulario_aliado_registro r JOIN formulario_aliados a ON a.id=r.aliado_id JOIN aliados_manuales m ON m.id=r.manual_id AND m.activo=1 LIMIT 1')->fetch_assoc();$ally=(int)$perfil['aliado_id'];$token=$perfil['token'];
$db->query("UPDATE formulario_aliado_registro SET publicado=1,habilitado=1 WHERE aliado_id=$ally");
foreach(['bachillerato-286','bachillerato-general'] as $code)$db->query("INSERT IGNORE INTO formulario_aliado_programas VALUES ($ally,'$code')");
$form=new FormularioRegistroModel();
$datos=['nombre'=>'Prueba','apellido'=>'Unificación','fecha_nacimiento'=>'1990-01-01','movil'=>'7778889900','correo'=>'union@example.test','perfil_interes'=>'Bachillerato General','lugar_laboras'=>'','cargo_puesto'=>'','estado_id'=>1,'municipio_id'=>1,'creado_por'=>null,'origen'=>'PUBLICO','aliado_token'=>$token];
$record=$form->guardar($datos);
$oldKey=hash('sha256',json_encode([$datos['correo'],$datos['movil'],$datos['fecha_nacimiento'],'bachillerato-286'],JSON_UNESCAPED_UNICODE));
$db->query("UPDATE formulario_aliado_procedencias SET programa_codigo='bachillerato-286',clave='$oldKey' WHERE tipo='registro' AND registro_id=$record");
$db->query("UPDATE formulario_registros SET perfil_interes='Bachillerato 286' WHERE id=$record");
// Inscripción exclusiva sin perfil de Registro: conservar su token y su ID.
$insToken=bin2hex(random_bytes(32));$slug='union-inscripcion-'.bin2hex(random_bytes(5));
$db->query("INSERT INTO formulario_aliados (slug,nombre,ubicacion,token,activo) VALUES ('$slug','Prueba Inscripción','México','$insToken',1)");$insAlly=(int)$db->insert_id;
foreach(['bachillerato-general','bachillerato-286'] as $code)$db->query("INSERT INTO formulario_aliado_programas VALUES ($insAlly,'$code')");
$insDatos=array_replace($datos,['aliado_token'=>$insToken,'origen'=>'PUBLICO_INSCRIPCION','correo'=>'union-inscripcion@example.test','movil'=>'7778889901']);
$insRecord=$form->guardar($insDatos);
$insKey=hash('sha256',json_encode([$insDatos['correo'],$insDatos['movil'],$insDatos['fecha_nacimiento'],'bachillerato-286'],JSON_UNESCAPED_UNICODE));
$db->query("UPDATE formulario_aliado_procedencias SET programa_codigo='bachillerato-286',clave='$insKey' WHERE tipo='inscripcion' AND registro_id=$insRecord");
$db->query("UPDATE formulario_inscripciones SET perfil_interes='Bachillerato 286' WHERE id=$insRecord");
$conv=(int)$db->query('SELECT id FROM convocatorias ORDER BY id LIMIT 1')->fetch_assoc()['id'];
$db->query("UPDATE convocatorias SET subtipo_convocatoria='bachillerato-286',titulo='Convocatoria Bachillerato 286 vigente' WHERE id=$conv");
$envio=(int)$db->query('SELECT COALESCE(MAX(id),0)+1 FROM aliados_convocatorias_envios')->fetch_row()[0];
$envioColumns=array_flip(array_column($db->query('SHOW COLUMNS FROM aliados_convocatorias_envios')->fetch_all(MYSQLI_ASSOC),'Field'));
$envioData=array_intersect_key(['id'=>$envio,'seguimiento_id'=>10,'cuenta_clave_usuario_id'=>2,'destinatario'=>'fixture@example.test','mensaje'=>'Contenido original del correo','convocatoria_titulo'=>'Difusión Bachillerato 286'],$envioColumns);
$values=array_map(fn($v)=>"'".$db->real_escape_string((string)$v)."'",array_values($envioData));
$db->query('INSERT INTO aliados_convocatorias_envios (`'.implode('`,`',array_keys($envioData)).'`) VALUES ('.implode(',',$values).')');
$db->query("INSERT INTO formulario_aliado_convocatorias (aliado_id,convocatoria_id,programa_codigo,formulario) VALUES ($ally,$conv,'bachillerato-286','registro')");
$_SESSION=['usuario_id'=>4,'rol'=>'Marketing','rol_id'=>5,'permisos'=>['convenios.ver','convocatorias.ver','convocatorias.crear','formularios_aliados.gestionar_enlaces']];
$service=new AliadoRegistroService($db);
$catalog=$service->catalogo();
$check(count(array_filter($catalog,fn($p)=>$p['codigo']==='bachillerato-general'))===1&&!in_array('bachillerato-286',array_column($catalog,'codigo'),true),'catálogo y edición muestran una opción incluso antes de migrar');
$exclusive=(new FormularioAliadoService($db))->resolver($token,false,'registro');
$check(count(array_filter($exclusive['programas'],fn($p)=>$p['codigo']==='bachillerato-general'))===1,'formulario exclusivo no duplica Bachillerato');
$migration=new UnificarBachillerato($db);$before=$migration->snapshot();$report=$migration->check();
$check($report['acciones']>0&&$migration->snapshot()===$before,'check detecta cambios sin escribir');
$counts=[];foreach(['convocatorias','formulario_registros','formulario_inscripciones','formulario_aliado_procedencias'] as $table)$counts[$table]=(int)$db->query("SELECT COUNT(*) FROM `$table`")->fetch_row()[0];
// Fallo después de modificar varias tablas: la transacción debe revertirlo todo.
$db->query("CREATE TRIGGER prueba_union_fallo BEFORE UPDATE ON formulario_aliado_procedencias FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Fallo simulado de prueba'");
$reject(fn()=>$migration->apply($private),'fallo intermedio no deja una migración parcial');
$check($migration->snapshot()===$before,'rollback repone todas las filas afectadas');
$db->query('DROP TRIGGER prueba_union_fallo');
$path=$migration->apply($private);$after=$migration->snapshot();
$check(is_file($path)&&$migration->check()['acciones']===0,'unificación y respaldo confirmados');
$check((int)$db->query("SELECT COUNT(*) FROM formulario_programas WHERE codigo='bachillerato-286'")->fetch_row()[0]===0,'entrada duplicada retirada del catálogo');
$check((int)$db->query("SELECT COUNT(*) FROM formulario_aliado_programas WHERE aliado_id=$ally AND programa_codigo='bachillerato-general'")->fetch_row()[0]===1,'asignaciones duplicadas fusionadas sin perder autorización');
foreach($counts as $table=>$count)$check((int)$db->query("SELECT COUNT(*) FROM `$table`")->fetch_row()[0]===$count,"IDs y cantidad conservados: $table");
$check($db->query("SELECT perfil_interes FROM formulario_registros WHERE id=$record")->fetch_row()[0]==='Bachillerato General','prospectos y Registro usan nombre único');
$check($db->query("SELECT perfil_interes FROM formulario_inscripciones WHERE id=$insRecord")->fetch_row()[0]==='Bachillerato General','Inscripción usa nombre único sin cambiar su ID');
$check($db->query("SELECT titulo FROM convocatorias WHERE id=$conv")->fetch_row()[0]==='Convocatoria Bachillerato General vigente','título y clasificación histórica actualizados');
$check($db->query("SELECT convocatoria_titulo FROM aliados_convocatorias_envios WHERE id=$envio")->fetch_row()[0]==='Difusión Bachillerato General','historial conserva el envío y normaliza el título del programa');
$check($form->guardar($datos)===$record,'reenvío posterior a migración conserva el ID previo');
$datos['perfil_interes']='Bachillerato 286';$check($form->guardar($datos)===$record,'solicitud antigua conserva la deduplicación y procedencia');
$insDatos['perfil_interes']='Bachillerato 286';$check($form->guardar($insDatos)===$insRecord,'reenvío de Inscripción conserva el ID y enlace originales');
$check($migration->apply($private)===null&&$migration->snapshot()===$after,'segundo apply no modifica nada');
$stable=$db->query("SELECT * FROM convocatorias WHERE id=$conv")->fetch_assoc();$auto='';
foreach($db->query('SHOW COLUMNS FROM convocatorias')->fetch_all(MYSQLI_ASSOC) as $column)if(stripos($column['Extra'],'on update')!==false){$field=$column['Field'];$auto.=",`$field`='".$db->real_escape_string((string)$stable[$field])."'";}
$db->query("UPDATE convocatorias SET titulo='Convocatoria Bachillerato General editada después'$auto WHERE id=$conv");
$reject(fn()=>$migration->restore($path),'restauración bloquea cambios posteriores');
$db->query("UPDATE convocatorias SET titulo='Convocatoria Bachillerato General vigente'$auto WHERE id=$conv");
$migration->restore($path);$check($migration->snapshot()===$before,'restauración exacta de catálogo, relaciones y datos históricos');
$check((int)$db->query('SELECT @@FOREIGN_KEY_CHECKS')->fetch_row()[0]===1,'claves foráneas permanecen activas');
// Una extensión desconocida nunca se omite silenciosamente.
$db->query("CREATE TABLE prueba_union_referencia (id INT PRIMARY KEY,programa_codigo VARCHAR(64),FOREIGN KEY (programa_codigo) REFERENCES formulario_programas(codigo)) ENGINE=InnoDB");
$db->query("INSERT INTO prueba_union_referencia VALUES (1,'bachillerato-286')");
$reject(fn()=>new UnificarBachillerato($db),'referencia adicional no revisada detiene la migración');
$db->query('DROP TABLE prueba_union_referencia');
// Dejar la réplica unificada para las pruebas de navegador siguientes.
$migration->apply($private);
echo "PASS $checks comprobaciones de unificación, SQL reversible, autorización y duplicados. BD sintética.\n";
